<?php
namespace App\Exports;use App\Models\TrainingProgram;use Maatwebsite\Excel\Concerns\{FromCollection,WithHeadings,WithMapping};class TrainingProgramExport implements FromCollection,WithHeadings,WithMapping{public function __construct(private TrainingProgram$p){}public function collection(){return$this->p->items()->with(['needs','responsible'])->get();}public function headings():array{return['Actividad','Tipo','Necesidades','Origen','Población','Responsable','Mes','Fecha prevista','Duración estimada','Modalidad','Prioridad','Estado'];}public function map($i):array{return[$i->title,config('training.training_types.'.$i->training_type),$i->needs->pluck('title')->implode('; '),$i->needs->pluck('origin_type')->map(fn($o)=>config('training.need_origins.'.$o))->implode('; '),$i->target_population_description,$i->responsible?->nombre_completo??$i->external_responsible,$i->planned_month,$i->planned_date?->format('d/m/Y'),$i->estimated_duration_minutes,config('training.modalities.'.$i->planned_modality),$i->priority,$i->status];}}
